/**
 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
 * it render the right branch, and does the price it renders stay announceable.
 *
 * Formatting is deliberately not asserted here — it happens at the page
 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
 * not a defensive edge case.
 *
 * Every render is wrapped: the atom calls `useIntl()` for Was/Now labels, which throws outside
 * an `IntlProvider` (react-intl's `invariantIntlContext`). `.storybook/preview.tsx` supplies
 * one for stories; Vitest has no global provider, so it is supplied here.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmProductPrice } from './index';

/** The ids the component asks for. Repeated deliberately — see the sourcing test below. */
const WAS_LABEL_ID = 'product_view.label.was_price';
const NOW_LABEL_ID = 'product_view.label.now_price';

/**
 * `locale` matches `defaultLocale` so react-intl treats an absent message as the ordinary
 * fallback-to-`defaultMessage` path rather than a missing-translation error.
 */
const renderWithIntl = (ui: React.ReactElement, messages?: Record<string, string>) =>
  render(
    <IntlProvider locale="en-AU" defaultLocale="en-AU" messages={messages}>
      {ui}
    </IntlProvider>,
  );

describe('ZimmProductPrice', () => {
  test('renders the caller-formatted string verbatim', () => {
    renderWithIntl(<ZimmProductPrice currentPrice="HK$6,200.00" />);
    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
    // page's decisions, and re-deriving any of them here would diverge per storefront.
    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
  });

  test('announces the price through a polite atomic live region', () => {
    const { container } = renderWithIntl(<ZimmProductPrice currentPrice="HK$6,200.00" />);

    // A variant change swaps this string with no focus move, so WCAG 2.2 AA 4.1.3 needs the
    // update announced. Both attributes are asserted: dropping `aria-atomic` would let a screen
    // reader announce only the characters that differ instead of the whole price, and neither
    // loss shows up on screen, so nothing else would catch it.
    const price = screen.getByTestId('product-price');
    expect(price).toHaveAttribute('aria-live', 'polite');
    expect(price).toHaveAttribute('aria-atomic', 'true');

    // The live region is the price element itself, not an extra hidden twin. Asserted because
    // the single-node shape is load-bearing, not incidental: `ZimmProductContent` renders this
    // atom into a flex column whose own `play` tests assert that column's exact child count, so
    // a second node here fails them from another folder.
    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
    expect(container.firstChild).toBe(price);
  });

  // SFCC-236 — card-grid reuse opt-out. A PLP renders many of these atoms and the price never
  // changes post-mount, so the live region is unnecessary DOM/AT overhead there.
  test('omits aria-live and aria-atomic entirely when isLive is false', () => {
    const { container } = renderWithIntl(<ZimmProductPrice currentPrice="$595.00" isLive={false} />);
    const price = screen.getByTestId('product-price');

    // Omitted entirely, not disabled via aria-live="off" — see the prop's JSDoc.
    expect(price).not.toHaveAttribute('aria-live');
    expect(price).not.toHaveAttribute('aria-atomic');
    expect(container.querySelectorAll('[aria-live]')).toHaveLength(0);
  });

  // PRC-09 — Was/Now sale treatment
  test('renders Was and Now spans when originalPrice is supplied', () => {
    renderWithIntl(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);

    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
  });

  test('combined textContent includes a separator space so aria-atomic reads correctly', () => {
    // With aria-atomic="true" the whole container is read as one utterance. Without a text
    // node between the two spans the announcement is "Was $795.00Now $595.00" — no separator.
    renderWithIntl(<ZimmProductPrice currentPrice="$595.00" originalPrice="$795.00" />);
    expect(screen.getByTestId('product-price').textContent).toBe('Was $795.00 Now $595.00');
  });

  test('Was/Now labels come from the intl provider, not from literals in the component', () => {
    // Guards against regression to hardcoded English strings. The test above passes either
    // way because `defaultMessage` and the old literal are the same string; supplying a
    // different message for the same id is the only thing that tells them apart.
    renderWithIntl(<ZimmProductPrice currentPrice="595,00 €" originalPrice="795,00 €" />, {
      [WAS_LABEL_ID]: 'War {price}',
      [NOW_LABEL_ID]: 'Jetzt {price}',
    });
    expect(screen.getByTestId('product-was-price').textContent).toBe('War 795,00 €');
    expect(screen.getByTestId('product-now-price').textContent).toBe('Jetzt 595,00 €');
  });

  test('renders only the standard price when originalPrice is absent', () => {
    renderWithIntl(<ZimmProductPrice currentPrice="$595.00" />);

    expect(screen.queryByTestId('product-was-price')).not.toBeInTheDocument();
    expect(screen.queryByTestId('product-now-price')).not.toBeInTheDocument();
    expect(screen.getByTestId('product-price')).toHaveTextContent('$595.00');
  });

  test('live region remains a single element in the sale variant', () => {
    // The live region must still be exactly one node (the chakra.p), even though its children
    // change. Two nodes would let ZimmProductContent's play tests break (child-count assertions).
    const { container } = renderWithIntl(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);
    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
  });

  // CodeRabbit a11y fix: live region must stay in the AT tree during loading so the
  // price announcement fires when the fetch settles.
  test('live region stays in the AT and preserves element identity across the loading transition', () => {
    const { rerender } = renderWithIntl(
      <ZimmProductPrice isLoading={true} currentPrice="$450.00" originalPrice="$595.00" />,
    );

    const region = screen.getByTestId('product-price');
    // aria-hidden absence is required but not sufficient — visibility:hidden also removes the
    // element from the AT. opacity:0 is the correct visual-hiding technique here.
    expect(region).not.toHaveAttribute('aria-hidden');
    expect(region).not.toHaveStyle({ visibility: 'hidden' });
    expect(region).toHaveAttribute('aria-live', 'polite');

    // Same DOM node after loading resolves — React reuses the chakra.p at the same position
    // so the AT's registered live region is preserved and announces the price on settle.
    rerender(
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <ZimmProductPrice isLoading={false} currentPrice="$450.00" originalPrice="$595.00" />
      </IntlProvider>,
    );
    expect(screen.getByTestId('product-price')).toBe(region);
    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
  });

  // SFCC-236 — same opt-out, exercised on the loading/skeleton branch's own aria-live literal
  // (a separate JSX call site from the loaded-path test above).
  test('omits aria-live and aria-atomic during the loading state when isLive is false', () => {
    const { container } = renderWithIntl(
      <ZimmProductPrice isLoading={true} currentPrice="$450.00" originalPrice="$595.00" isLive={false} />,
    );
    const price = screen.getByTestId('product-price');

    expect(price).not.toHaveAttribute('aria-live');
    expect(price).not.toHaveAttribute('aria-atomic');
    expect(container.querySelectorAll('[aria-live]')).toHaveLength(0);
  });

  test.each([undefined, ''])('renders nothing for %s', (currentPrice) => {
    const { container } = renderWithIntl(<ZimmProductPrice currentPrice={currentPrice} />);
    // `''` is what the page's mapper produces for a product with no price, so this branch is
    // reached in production. An empty styled node would still consume a gap in
    // ZimmProductContent's flex column, leaving a visible hole between name and description.
    //
    // Asserted as an empty container rather than an absent testid: a node that still carried the
    // recipe's styling but had lost its `data-testid` would satisfy the narrower check while
    // being precisely the gap-consuming element this guard exists to prevent.
    expect(container).toBeEmptyDOMElement();
  });
});

