17	const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';
18	
19	/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
20	export type ZimmColourSwatchValue = {
21	  value: string;
22	  name: string;
23	  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
24	  imageUrl?: string;
25	  /** Router destination URL for this colour. Absent on the quick-view modal path. */
26	  href?: string;
27	  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
28	  orderable?: boolean;
29	  /**
30	   * When true, clicking navigates via a native anchor (full page reload) rather than a router
31	   * Link. Set for related-colour swatches (SFCC-708) that link to a different master product.
32	   */
33	  forceReload?: boolean;
34	};
35	
36	type ZimmColourSwatchGroupProps = {
37	  values: ZimmColourSwatchValue[];
38	  /** Currently selected colour value (from URL / variation params). */
39	  selectedValue?: string;
40	  /**
41	   * Display label for the colour group. Defaults to the i18n "Colour" value.
42	   * Pass an explicit value when the SFCC attribute display name differs from the default.
43	   */
44	  label?: string;
45	  /**
46	   * Selection callback for the linkless path (no `href` on values). Called on click and
47	   * arrow-key navigation. Not needed on the PDP, where each value carries an `href` and
48	   * selection is handled by router navigation.
49	   */
50	  onSelect?: (value: string) => void;
51	};
52	
53	/**
54	 * Molecule — the full colour-swatch group: label row (name + pagination arrows), and a
55	 * `[role=radiogroup]` swatch strip of `ZimmColourSwatch` atoms with roving tabindex and
56	 * keyboard navigation.
57	 *
58	 * When only one offered colour exists, the label and name render but the swatch row is
59	 * suppressed (nothing to choose between). Colours without a swatch image or marked
60	 * non-orderable are withheld entirely.
61	 */
62	export const ZimmColourSwatchGroup = ({ values, selectedValue, label, onSelect }: ZimmColourSwatchGroupProps) => {
63	  const intl = useIntl();
64	  const groupLabel = label ?? intl.formatMessage(messages.groupLabel);
65	  const labelText = label != null ? `${label}:` : intl.formatMessage(messages.label);
66	
67	  // Filter to only offered (orderable + swatch image populated) colours.
68	  const offered = values.filter((v) => Boolean(v.imageUrl) && v.orderable !== false);
69	
70	  const isPaginated = offered.length > SWATCHES_PER_PAGE;
71	  const pageCount = Math.ceil(offered.length / SWATCHES_PER_PAGE);
72	
73	  const [page, setPage] = useState(0);
74	
75	  // Auto-advance to the page containing the pre-selected value on mount or when selectedValue
76	  // changes (e.g. browser back/forward lands on a colour that is off page 0).
77	  // When selectedValue is absent or not in the offered set, clamp to the highest valid page so
78	  // all remaining swatches stay visible after the offered set shrinks (e.g. a colour becomes
79	  // unavailable while the user is on a later page).
80	  useEffect(() => {
81	    const idx = offered.findIndex((v) => v.value === selectedValue);
82	    if (idx >= 0) {
83	      setPage(Math.floor(idx / SWATCHES_PER_PAGE));
84	    } else {
85	      const pc = Math.ceil(offered.length / SWATCHES_PER_PAGE);
86	      setPage((p) => Math.min(p, Math.max(0, pc - 1)));
87	    }
88	    // offered.length captures filter changes; selectedValue tracks URL/prop changes.
89	  }, [selectedValue, offered.length]);
90	
91	  // Roving tabindex: the focused atom is either the selected one or index 0 (no selection).
92	  const selectedIndex = offered.findIndex((v) => v.value === selectedValue);
93	  const tabFocusIndex = selectedIndex >= 0 ? selectedIndex : 0;
94	
95	  // True when the globally-selected swatch falls on the current visual page.
96	  const isTabFocusOnPage = Math.floor(tabFocusIndex / SWATCHES_PER_PAGE) === page;
97	
98	  // Focus management after keyboard navigation. After history.push updates the URL and React
99	  // re-renders with a new selectedValue, focus the newly-focusable atom imperatively so the
100	  // shopper doesn't have to re-tab to continue arrow-key navigation.
101	  const radioGroupRef = useRef<HTMLDivElement>(null);
102	  const hasNavigated = useRef(false);
103	
104	  useEffect(() => {
105	    if (hasNavigated.current) {
106	      const focusable = radioGroupRef.current?.querySelector('[tabindex="0"]') as HTMLElement | null;
107	      focusable?.focus();
108	      hasNavigated.current = false;
109	    }
110	  }, [selectedValue]);
111	
112	  const history = useHistory();
113	
114	  const handleSwatchesKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
115	    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
116	    e.preventDefault();
117	
118	    // Derive current index from the focused element's data-swatch-value — a unique value
119	    // identity that survives duplicate display names (e.g. two shades both named "Bay Blue").
120	    const focusedValue = (document.activeElement as HTMLElement | null)
121	      ?.closest('[data-swatch-value]')
122	      ?.getAttribute('data-swatch-value');
123	    const focusedIndex = focusedValue ? offered.findIndex((v) => v.value === focusedValue) : -1;
124	    const currentIndex = focusedIndex >= 0 ? focusedIndex : tabFocusIndex;
125	
126	    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
127	    const nextIndex = isForward
128	      ? (currentIndex + 1) % offered.length
129	      : (currentIndex - 1 + offered.length) % offered.length;
130	
131	    const next = offered[nextIndex];
132	    const nextPage = Math.floor(nextIndex / SWATCHES_PER_PAGE);
133	
134	    setPage(nextPage);
135	    hasNavigated.current = true;
136	
137	    if (next.href) {
138	      if (next.forceReload) {
139	        window.location.href = next.href;
140	      } else {
141	        history.push(next.href);
142	      }
143	    } else {
144	      onSelect?.(next.value);
145	    }
146	  };
147	
148	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });
149	
150	  const selectedName = offered.find((v) => v.value === selectedValue)?.name ?? offered[0]?.name;
151	
152	  // No offered colours at all (every value failed the imageUrl/orderable filter) — suppress
153	  // the entire group including the label so a bare "Colour:" never appears on the PDP.
154	  if (offered.length === 0) return null;
155	
156	  return (
157	    <chakra.div __css={styles.root}>
158	      <chakra.div __css={styles.label}>
159	        <chakra.span textStyle="caption">{labelText}</chakra.span>
160	        {selectedName && (
161	          <chakra.span data-testid="pdp-colour-selected-name" __css={styles.labelName}>
162	            {selectedName}
163	          </chakra.span>
164	        )}
165	        {isPaginated && (
166	          <chakra.div __css={styles.pagination} aria-label={intl.formatMessage(messages.paginationGroupLabel)}>
167	            <chakra.button
168	              as="button"
169	              __css={styles.pageButton}
170	              aria-label={intl.formatMessage(messages.previous)}
171	              disabled={page === 0}
172	              onClick={() => setPage((p) => p - 1)}
173	            >
174	              <ChevronLeftIcon aria-hidden />
175	            </chakra.button>
176	            <chakra.button
177	              as="button"
178	              __css={styles.pageButton}
179	              aria-label={intl.formatMessage(messages.next)}
180	              disabled={page === pageCount - 1}
181	              onClick={() => setPage((p) => p + 1)}
182	            >
183	              <ChevronRightIcon aria-hidden />
184	            </chakra.button>
185	          </chakra.div>
186	        )}
187	      </chakra.div>
188	
189	      {offered.length > 1 && (
190	        <chakra.div
191	          role="radiogroup"
192	          aria-label={groupLabel}
193	          ref={radioGroupRef}
194	          __css={styles.swatches}
195	          onKeyDown={handleSwatchesKeyDown}
196	        >
197	          {offered.map((v, i) => {
198	            const isOnPage = Math.floor(i / SWATCHES_PER_PAGE) === page;
199	            // Off-page swatches are always removed from the tab order (tabIndex="-1"), even
200	            // when they're the globally-selected colour, so Tab focus never lands on a
201	            // visually-hidden element. When the selected swatch is off-page (the user manually
202	            // paged without changing colour), the first on-page swatch becomes the tab stop.
203	            const isFocusable = isOnPage && (isTabFocusOnPage ? i === tabFocusIndex : i === page * SWATCHES_PER_PAGE);
204	
205	            return (
206	              // All swatches are always in the DOM so screen readers can navigate the full set
207	              // and aria-posinset/aria-setsize reports the correct total count ("N of M" where
208	              // M = all offered colours, not just the current page). Off-page swatches are
209	              // absolutely positioned — removed from the flex flow so they don't widen the row —
210	              // and clip-path'd to a 0×0 visible area so they are invisible on screen while
211	              // remaining in the accessibility tree.
212	              <chakra.span
213	                key={v.value}
214	                data-swatch-value={v.value}
215	                style={isOnPage ? undefined : { position: 'absolute', clipPath: 'inset(50%)' }}
216	              >
217	                <ZimmColourSwatch
218	                  name={v.name}
219	                  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
220	                  imageUrl={v.imageUrl!}
221	                  href={v.href}
222	                  forceReload={v.forceReload}
223	                  onClick={onSelect ? () => onSelect(v.value) : undefined}
224	                  isSelected={v.value === selectedValue}
225	                  isFocusable={isFocusable}
226	                  posInSet={i + 1}
227	                  setSize={offered.length}
228	                />
229	              </chakra.span>
230	            );
231	          })}
232	        </chakra.div>
233	      )}
234	    </chakra.div>
235	  );
236	};
237	
238	export default ZimmColourSwatchGroup;
